//! The `codex app-server` protocol, v2 methods, as generated by
//! `codex app-server generate-json-schema` at 0.167.1 and seen against the fake provider.

use std::collections::HashMap;

use serde_json::{Value, json};
use x100_core::driver::{ContextFill, Failure};
use x100_core::ledger::CostBasis;
use x100_core::money::{Money, Price, Usage};

use super::{VERSIONS, effort_name};
use crate::failure::classify_codex;
use crate::handle::InputError;
use crate::harness::{DriverSpec, Permissions};
use crate::output::{Decision, DriverOutput, PermissionId, PermissionRequest, Spent, TurnEnd};
use crate::protocol::{Effects, Input, Protocol, Ready};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Request {
    Initialize,
    ThreadStart,
    TurnStart,
    Other,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Phase {
    Turn,
    Compaction,
}

pub(crate) struct CodexRpc {
    start_pack: String,
    model: String,
    effort: &'static str,
    cwd: String,
    approval: &'static str,
    expects_tools: bool,
    price: Price,
    next_id: u64,
    requests: HashMap<u64, Request>,
    version: String,
    warnings: Vec<String>,
    thread: Option<String>,
    turn: Option<String>,
    phase: Option<Phase>,
    interrupt_waiting: bool,
    spent: Spent,
    /// The last request's tokens and the window, for context fill at the end of a turn.
    last: Option<(u64, u64)>,
    /// Each file change's details, which its approval request leaves out.
    changes: HashMap<String, Value>,
    /// Pending approvals: the id x100 gave each, and the JSON-RPC id to answer.
    approvals: HashMap<String, Value>,
}

fn nothing_spent() -> Spent {
    Spent {
        usage: Usage::default(),
        cost: Money::ZERO,
        basis: CostBasis::Listed,
    }
}

impl CodexRpc {
    pub(crate) fn new(spec: &DriverSpec, price: Price) -> Self {
        Self {
            start_pack: spec.start_pack.clone(),
            model: spec.model.0.clone(),
            effort: effort_name(spec.effort),
            cwd: spec.dir.display().to_string(),
            approval: match spec.permissions {
                Permissions::AllowAll => "never",
                Permissions::AskDaemon => "untrusted",
            },
            expects_tools: spec.tools.is_some(),
            price,
            next_id: 0,
            requests: HashMap::new(),
            version: String::new(),
            warnings: Vec::new(),
            thread: None,
            turn: None,
            phase: None,
            interrupt_waiting: false,
            spent: nothing_spent(),
            last: None,
            changes: HashMap::new(),
            approvals: HashMap::new(),
        }
    }

    fn request(&mut self, kind: Request, method: &str, params: Value, fx: &mut Effects) {
        self.next_id += 1;
        self.requests.insert(self.next_id, kind);
        fx.send_json(
            &json!({ "jsonrpc": "2.0", "id": self.next_id, "method": method, "params": params }),
        );
    }

    fn on_response(&mut self, message: &Value, fx: &mut Effects) {
        let kind = message["id"]
            .as_u64()
            .and_then(|id| self.requests.remove(&id))
            .unwrap_or(Request::Other);
        let error = message.get("error");
        let result = &message["result"];
        match (kind, error) {
            (Request::Initialize, None) => {
                // The user agent is "<client name>/<codex version> (...)".
                let agent = result["userAgent"].as_str().unwrap_or_default();
                let version = agent
                    .split_once('/')
                    .map(|(_, rest)| rest.split_whitespace().next().unwrap_or_default())
                    .unwrap_or_default();
                match VERSIONS.check(version) {
                    Ok(warning) => {
                        self.version = version.to_owned();
                        self.warnings.extend(warning);
                    }
                    Err(reason) => {
                        fx.started = Some(Err(reason));
                        return;
                    }
                }
                fx.send_json(&json!({ "jsonrpc": "2.0", "method": "initialized" }));
                let params = json!({
                    "model": self.model,
                    "cwd": self.cwd,
                    "approvalPolicy": self.approval,
                    "sandbox": "danger-full-access",
                    "developerInstructions": self.start_pack,
                    "ephemeral": true,
                });
                self.request(Request::ThreadStart, "thread/start", params, fx);
            }
            (Request::ThreadStart, None) => {
                self.thread = result["thread"]["id"].as_str().map(str::to_owned);
                fx.started = Some(Ok(Ready {
                    version: self.version.clone(),
                    warnings: std::mem::take(&mut self.warnings),
                }));
            }
            (Request::TurnStart, None) => {
                self.turn = result["turn"]["id"].as_str().map(str::to_owned);
                if std::mem::take(&mut self.interrupt_waiting) {
                    self.interrupt(fx);
                }
            }
            (Request::Initialize | Request::ThreadStart, Some(error)) => {
                fx.started = Some(Err(format!("Codex refused to start: {error}")));
            }
            (Request::TurnStart, Some(error)) => fx.emit(DriverOutput::Failed(Failure::Error {
                detail: format!("Codex refused the turn: {error}"),
                provider: None,
            })),
            (Request::Other, Some(error)) => {
                fx.emit(DriverOutput::Warning(format!(
                    "Codex answered with an error: {error}"
                )));
            }
            (Request::Other, None) => {}
        }
    }

    fn on_server_request(&mut self, message: &Value, fx: &mut Effects) {
        let id = message["id"].clone();
        let params = &message["params"];
        let (tool, input) = match message["method"].as_str() {
            Some("item/commandExecution/requestApproval") => (
                "command",
                json!({ "command": params["command"], "cwd": params["cwd"] }),
            ),
            Some("item/fileChange/requestApproval") => {
                let item = params["itemId"].as_str().unwrap_or_default();
                let changes = self.changes.get(item).cloned().unwrap_or(Value::Null);
                ("file_change", json!({ "changes": changes }))
            }
            other => {
                fx.send_json(&json!({
                    "jsonrpc": "2.0",
                    "id": id,
                    "error": { "code": -32601, "message": format!("x100 does not handle {other:?}") },
                }));
                return;
            }
        };
        let ours = format!("rpc-{id}");
        self.approvals.insert(ours.clone(), id);
        fx.emit(DriverOutput::PermissionRequest(PermissionRequest {
            id: PermissionId(ours),
            tool: tool.to_owned(),
            input,
        }));
    }

    fn on_item(&mut self, item: &Value, completed: bool, fx: &mut Effects) {
        let id = item["id"].as_str().unwrap_or_default().to_owned();
        let status = item["status"].as_str().unwrap_or_default();
        match (item["type"].as_str(), completed) {
            (Some("agentMessage"), true) => {
                let text = item["text"].as_str().unwrap_or_default();
                if !text.is_empty() {
                    fx.emit(DriverOutput::Text(text.to_owned()));
                }
            }
            (Some("commandExecution"), false) => fx.emit(DriverOutput::ToolCall {
                id,
                name: "command".into(),
                input: json!({ "command": item["command"], "cwd": item["cwd"] }),
            }),
            (Some("commandExecution"), true) => {
                let exit = item["exitCode"].as_i64();
                let output = item["aggregatedOutput"]
                    .as_str()
                    .map(str::to_owned)
                    .unwrap_or_else(|| format!("{status}, exit code {exit:?}"));
                fx.emit(DriverOutput::ToolResult {
                    id,
                    output,
                    is_error: status != "completed" || exit.is_some_and(|c| c != 0),
                });
            }
            (Some("fileChange"), false) => {
                self.changes.insert(id.clone(), item["changes"].clone());
                fx.emit(DriverOutput::ToolCall {
                    id,
                    name: "file_change".into(),
                    input: json!({ "changes": item["changes"] }),
                });
            }
            (Some("fileChange"), true) => fx.emit(DriverOutput::ToolResult {
                id,
                output: status.to_owned(),
                is_error: status != "completed",
            }),
            (Some("mcpToolCall"), false) => fx.emit(DriverOutput::ToolCall {
                id,
                name: format!(
                    "mcp__{}__{}",
                    item["server"].as_str().unwrap_or_default(),
                    item["tool"].as_str().unwrap_or_default()
                ),
                input: item["arguments"].clone(),
            }),
            (Some("mcpToolCall"), true) => {
                let output = match item["result"]["content"].as_array() {
                    Some(parts) => parts
                        .iter()
                        .filter_map(|p| p["text"].as_str())
                        .collect::<Vec<_>>()
                        .join("\n"),
                    None => item["error"].to_string(),
                };
                fx.emit(DriverOutput::ToolResult {
                    id,
                    output,
                    is_error: status != "completed",
                });
            }
            _ => {}
        }
    }

    /// One model request's tokens, priced on their own so a long-context tier applies per request.
    fn on_token_usage(&mut self, usage: &Value) {
        let last = &usage["last"];
        let n = |k: &str| last[k].as_u64().unwrap_or(0);
        let (input, cached, written, output) = (
            n("inputTokens"),
            n("cachedInputTokens"),
            n("cacheWriteInputTokens"),
            n("outputTokens"),
        );
        let request = Usage {
            input: input.saturating_sub(cached).saturating_sub(written),
            output,
            cache_read: cached,
            cache_write_short: written,
            cache_write_long: 0,
        };
        self.spent.usage += request;
        self.spent.cost += self.price.cost(&request);
        if let Some(window) = usage["modelContextWindow"].as_u64() {
            self.last = Some((input + output, window));
        }
    }

    fn on_turn_completed(&mut self, turn: &Value, fx: &mut Effects) {
        let phase = self.phase.take();
        self.turn = None;
        let spent = std::mem::replace(&mut self.spent, nothing_spent());
        fx.emit(DriverOutput::Spent(spent));
        match turn["status"].as_str() {
            Some("failed") => {
                let error = &turn["error"];
                let detail = error["message"]
                    .as_str()
                    .unwrap_or("the turn failed")
                    .to_owned();
                let provider = classify_codex(&error["codexErrorInfo"], &detail);
                fx.emit(DriverOutput::Failed(Failure::Error { detail, provider }));
            }
            Some("interrupted") => fx.emit(DriverOutput::TurnEnded(TurnEnd::Interrupted)),
            _ if phase == Some(Phase::Compaction) => {
                // The last request was the summary, so its size says nothing about the context
                // left; the next turn reports it.
                self.last = None;
                fx.emit(DriverOutput::Compacted);
            }
            _ => {
                if let Some((used, window)) = self.last {
                    fx.emit(DriverOutput::Context(ContextFill { used, window }));
                }
                fx.emit(DriverOutput::TurnEnded(TurnEnd::Completed));
            }
        }
    }

    fn on_notification(&mut self, message: &Value, fx: &mut Effects) {
        let params = &message["params"];
        match message["method"].as_str() {
            Some("item/started") => self.on_item(&params["item"], false, fx),
            Some("item/completed") => self.on_item(&params["item"], true, fx),
            Some("thread/tokenUsage/updated") => self.on_token_usage(&params["tokenUsage"]),
            Some("turn/completed") => self.on_turn_completed(&params["turn"], fx),
            Some("mcpServer/startupStatus/updated")
                if self.expects_tools && params["status"] == "failed" =>
            {
                fx.emit(DriverOutput::Warning(format!(
                    "Codex could not reach the daemon's tools: {}",
                    params["error"]
                )));
            }
            Some("configWarning") => fx.emit(DriverOutput::Warning(format!(
                "Codex configuration: {}",
                params["summary"]
            ))),
            _ => {}
        }
    }

    fn interrupt(&mut self, fx: &mut Effects) {
        match (&self.thread, &self.turn) {
            (Some(thread), Some(turn)) => {
                let params = json!({ "threadId": thread, "turnId": turn });
                self.request(Request::Other, "turn/interrupt", params, fx);
            }
            // The turn's id arrives with the answer to turn/start; interrupt once it does.
            _ => self.interrupt_waiting = true,
        }
    }
}

impl Protocol for CodexRpc {
    fn begin(&mut self, fx: &mut Effects) {
        let params = json!({
            "clientInfo": { "name": "x100", "title": null, "version": env!("CARGO_PKG_VERSION") },
            "capabilities": null,
        });
        self.request(Request::Initialize, "initialize", params, fx);
    }

    fn line(&mut self, line: &str, fx: &mut Effects) {
        let Ok(message) = serde_json::from_str::<Value>(line) else {
            fx.emit(DriverOutput::Failed(Failure::StreamBroke));
            return;
        };
        match (message.get("id").is_some(), message.get("method").is_some()) {
            (true, true) => self.on_server_request(&message, fx),
            (true, false) => self.on_response(&message, fx),
            (false, true) => self.on_notification(&message, fx),
            (false, false) => {}
        }
    }

    fn input(&mut self, input: Input, fx: &mut Effects) -> Result<(), InputError> {
        let thread = self.thread.clone().unwrap_or_default();
        match input {
            Input::Turn(text) => {
                self.phase = Some(Phase::Turn);
                let params = json!({
                    "threadId": thread,
                    "input": [{ "type": "text", "text": text, "text_elements": [] }],
                    "effort": self.effort,
                });
                self.request(Request::TurnStart, "turn/start", params, fx);
            }
            Input::Compact => {
                self.phase = Some(Phase::Compaction);
                let params = json!({ "threadId": thread });
                self.request(Request::Other, "thread/compact/start", params, fx);
            }
            Input::Interrupt => self.interrupt(fx),
            Input::Answer(PermissionId(id), decision) => {
                let Some(rpc_id) = self.approvals.remove(&id) else {
                    return Err(InputError::NoSuchRequest(PermissionId(id)));
                };
                // Codex takes no reason with a refusal; the model sees only that it was declined.
                let decision = match decision {
                    Decision::Allow => "accept",
                    Decision::Deny { .. } => "decline",
                };
                fx.send_json(
                    &json!({ "jsonrpc": "2.0", "id": rpc_id, "result": { "decision": decision } }),
                );
            }
        }
        Ok(())
    }
}
